// launch-factory: 문의 접수 조립. 순서: 요청 제한(DB) → 멱등 키 → 입력 검사 → Turnstile → 저장 → 운영자 알림 → (선택) 접수 확인.
// 개인정보는 최소만 저장한다(이름 선택·연락처·내용). 보유 기간은 일반 30일, 불만·분쟁 3년(Cron 이 지난 것을 지운다).
// 접수 확인 메일과 첫 응답 약속은 lib/launch/support.ts(제품 설정)가 정한다.
// 운영자 메일(INQUIRY_OWNER_EMAIL)이 없으면 문의 창구만 꺼진다 — inquiryEnabled() 가 false 이고 서비스는 접수를 provider_unavailable 로 거절한다.
import { hitRateLimit } from "@launch-factory/db"
import { createInquiryService, type InquiryService } from "@launch-factory/inquiry"
import { createRateLimiter, ipAddressFromEnv, warnNoIpOnce } from "@launch-factory/security/rate-limit"
import { createTurnstile } from "@launch-factory/security/turnstile"
import { DEFAULT_LOCALE, PRODUCT_NAME } from "@/lib/launch/config"
import { database } from "@/lib/launch/db"
import { env, optional, required } from "@/lib/launch/env"
import { mailer } from "@/lib/launch/mailer"
import { SUPPORT } from "@/lib/launch/support"

let cached: Promise<InquiryService> | undefined

export function inquiry(): Promise<InquiryService> {
  return (cached ??= build())
}

/**
 * 문의 알림을 받을 운영자 메일. **없으면 문의 창구만 꺼진다**(사이트는 켜진다 — 운영자 결정 2026-10-05, 미리보기 전 쪽 500 사고).
 * 있으면 켜지 않는 척 속이지 않고 형식을 본다(live-env.ts 가 켜질 때 z.email() 로 확인). mock 은 없으면 가짜 주소로 켠다 —
 * 메일은 콘솔에만 찍히므로 어디로도 나가지 않는다. LF_BUSINESS_EMAIL 로 대신하지 않는다: 그것은 바닥글에 공개하는 표시 주소이지 개인정보가 오는 창구가 아니다.
 */
export function inquiryOwnerEmail(): string | undefined {
  const set = optional("INQUIRY_OWNER_EMAIL")
  return set ?? (env().LF_MODE === "live" ? undefined : "owner@example.test")
}

/** 문의를 받는가. 쪽(/contact)이 폼 대신 안내를 그리고, 배포 확인이 경고를 낼 때 읽는다. 데이터베이스에 닿지 않는다 */
export const inquiryEnabled = (): boolean => inquiryOwnerEmail() !== undefined

async function build(): Promise<InquiryService> {
  const db = await database()
  const live = env().LF_MODE === "live"
  const ownerAddress = inquiryOwnerEmail()
  return createInquiryService({
    db,
    mailer: mailer(),
    // 믿을 IP 머리는 환경이 정한다(대장 D205). 인증 항목·보안 항목과 같은 함수라 같은 사람을 같은 IP 로 센다
    limiter: createRateLimiter({ store: { hit: (key, windowMs, now) => hitRateLimit(db, key, windowMs, now) }, ipAddress: ipAddressFromEnv(process.env), onNoIp: warnNoIpOnce() }),
    turnstile: createTurnstile(live ? { mode: "live", secretKey: required("TURNSTILE_SECRET_KEY") } : { mode: "mock" }),
    // 주소가 없으면 owner 를 빼 접수만 끈다: 접수는 provider_unavailable 로 거절하고, 파기 Cron·종류 변경은 그대로 된다
    ...(ownerAddress ? { owner: { email: ownerAddress, locale: DEFAULT_LOCALE } } : {}),
    productName: PRODUCT_NAME,
    receipt: SUPPORT.receipt,
    ...(SUPPORT.responseTime ? { responseTime: SUPPORT.responseTime } : {}),
  })
}

// launch-factory: 고객 지원 설정(K05·K06·K10). 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
// 문의 화면(/contact)과 접수 확인 메일이 이 값을 그대로 읽는다. 값은 제품이 정한다 — 공장 코드에는 실제 주소·시간을 넣지 않는다.
export const SUPPORT = {
  /**
   * 첫 응답 약속. 문의 화면과 접수 확인 메일에 같은 글로 실린다. **지킬 수 있는 시간만 적는다**(전자상거래법 §21①3 — 응답 담당이 없는데 약속하지 않는다).
   * null 이면 약속 줄을 싣지 않는다. 화면 언어(영어)와 같은 말로 적는다.
   */
  responseTime: "1 business day" as string | null,
  /** 접수 확인 메일을 보낼지(연락처가 이메일일 때만). 방문자가 적은 주소로 나가므로 요청 제한·Turnstile 이 남용을 막는 장치다 */
  receipt: true,
  /** 사람이 직접 읽는 문의 메일 주소(선택). null 이면 화면에 주소를 싣지 않는다 — 폼이 문의 창구다 */
  email: null as string | null,
}

// launch-factory: 문의 접수 경로(POST, FormData 또는 JSON). 429 + Retry-After · 봇 400 · 칸 오류 400 · 확인 불가 503 · 처리 중 409.
// 폼에 숨은 입력 둘을 더한다: Turnstile 토큰 `cf-turnstile-response`, 폼을 열 때 만든 `idempotencyKey`.
import { inquiry } from "@/lib/launch/inquiry"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function POST(request: Request) {
  return (await inquiry()).handler(request)
}

// launch-factory: 문의 파기 Cron(하루 한 번 권장). 보유 기간이 지난 문의를 지운다.
// vercel.json 에 `{ "crons": [{ "path": "/api/cron/inquiry", "schedule": "0 4 * * *" }] }` 를 더한다. CRON_SECRET 이 없으면 401 이다.
import { cronAuthorized, unauthorized } from "@/lib/launch/cron"
import { inquiry } from "@/lib/launch/inquiry"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  if (!cronAuthorized(request)) return unauthorized()
  return Response.json({ purged: await (await inquiry()).purgeExpired() })
}

"use server"
// launch-factory: 문의 서버 액션 — web-factory contact-form 블록의 submit 포트 모양이다(`(input: Record<string, string>) => Promise<ActionResult>`).
// IP 는 요청 머리에서 읽어 요청 제한 키에만 쓴다(저장하지 않는다).
import { headers } from "next/headers"
import { inquiry } from "@/lib/launch/inquiry"

export async function submitInquiry(input: Record<string, string>) {
  return (await inquiry()).action({ headers: new Headers(await headers()) })(input)
}

"use server"
// launch-factory: 내 신청 내역 서버 액션(계획 3c Task 5). 사용자 id 는 입력으로 받지 않는다 — 세션에서 읽는다(남의 것을 볼 수 없다).
//   myRequests: 로그인한 본인 문의 목록. 연락처·내용은 가린 앞부분만 내려간다(전체 내용·이름은 읽지도 않는다).
// 처리 상태 바꾸기(관리자·소유자)는 이 파일에 없다 — 관리 콘솔의 문의 구획(admin-sections/inquiries.ts)만 그 입구다(두 번째 입구 금지, 계획 3d).
import { messages } from "@launch-factory/i18n"
import { authPort } from "@/lib/launch/auth"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
import { inquiry } from "@/lib/launch/inquiry"

const signInRequired = () => ({ ok: false as const, formError: messages(DEFAULT_LOCALE).auth.signInRequired })
const impersonationBlocked = () => ({ ok: false as const, status: 403 as const, code: "impersonation_blocked" as const, formError: messages(DEFAULT_LOCALE).auth.impersonationBlocked })
const invalidInput = { ok: false as const, error: "invalid_input" as const }

/** 지금 로그인한 사람의 id. 로그아웃 → null(로그인 요구), 대리 세션 → "impersonated" */
async function session(): Promise<{ userId: string } | "impersonated" | null> {
  const s = await (await authPort()).session()
  if (!s.ok || !s.data) return null
  return s.data.impersonatedBy ? "impersonated" : { userId: s.data.userId }
}

/** 입력: { page? }(정수 1 이상). 모양이 틀리면 invalid_input */
export async function myRequests(input?: unknown) {
  const i = input === undefined ? {} : input
  if (typeof i !== "object" || i === null) return invalidInput
  const page = (i as Record<string, unknown>).page
  if (page !== undefined && !(typeof page === "number" && Number.isInteger(page) && page >= 1)) return invalidInput
  const who = await session()
  if (who === "impersonated") return impersonationBlocked()
  if (!who) return signInRequired()
  return { ok: true as const, data: await (await inquiry()).listMine(who.userId, page === undefined ? {} : { page: page as number }) }
}

// launch-factory: 관리 화면 구획 — 문의(계획 3d). 목록(처리 상태로 거르고 접수 번호·이름·연락처로 찾기) → 상세(전체 내용 + 답변 글타래) → 답변 저장 → 상태·불만 행동.
// 들어오는 사람: 문의 소유자(확인된 이메일이 INQUIRY_OWNER_EMAIL) 또는 관리자 — 예전 서버 액션(inquiry-admin.ts)과 같은 규칙이다. 규칙을 콘솔이 먼저 지키고, 서비스(lib/launch/inquiry)가 한 번 더 판정한다.
// 구획은 서버 액션이 아니라 문의 서비스를 직접 부른다(콘솔이 준 actor 를 그대로 넘긴다) — 문의를 바꾸는 입구는 이 구획 하나다.
// 개인정보: 표의 연락처 열은 콘솔이 가려서 내보낸다. 상세에는 답하는 데 필요해서 전체 값이 나가고(읽을 때마다 접속 기록이 한 줄 남는다), 행동 기록에는 폼 값이 없다.
import { defineSection, refuse, type Outcome } from "@launch-factory/admin-console"
import { INQUIRY_STATUSES, type StaffInquiry, type StaffInquiryItem } from "@launch-factory/inquiry"
import { inquiry, inquiryOwnerEmail } from "@/lib/launch/inquiry"

/** 서비스가 돌려주는 실패 이름 → 콘솔 실패 코드 */
const CODES: Record<string, string> = { forbidden: "forbidden", not_found: "not_found", invalid_input: "invalid_input", invalid_status: "invalid_input", invalid_kind: "invalid_input" }
const fail = (error: string) => refuse(CODES[error] ?? "action_failed")
const done = (r: { ok: true } | { ok: false; error: string }, message: string): Outcome => (r.ok ? { message } : fail(r.error))
const DISPUTE = ["complaint", "dispute"]

export const inquiriesSection = defineSection({
  id: "inquiries",
  part: "inquiry",
  label: "Inquiries",
  audience: { owner: inquiryOwnerEmail },
  statuses: INQUIRY_STATUSES,
  serverSearch: true, // 서버 검색: 접수 번호·이름·연락처 부분 일치(listInquiriesForStaff)
  columns: [
    { id: "reference", label: "Reference", kind: "text", primary: true },
    { id: "kind", label: "Kind", kind: "text", secondary: true },
    { id: "status", label: "Status", kind: "status", filter: true },
    { id: "name", label: "Name", kind: "contact", secondary: true },
    { id: "contact", label: "Contact", kind: "contact", secondary: true },
    { id: "createdAt", label: "Received", kind: "date" },
  ],
  list: async (actor, q) => {
    const r = await (await inquiry()).listForStaff(actor, { ...(q.status ? { status: q.status } : {}), ...(q.search ? { search: q.search } : {}), limit: q.limit, offset: q.offset })
    return r.ok ? r.data : fail(r.error)
  },
  key: (row: StaffInquiryItem) => row.reference,
  cells: (row) => ({ reference: row.reference, kind: row.kind, status: row.status, name: row.name, contact: row.contact, createdAt: row.createdAt }),
  load: async (actor, id): Promise<StaffInquiry | null | ReturnType<typeof refuse>> => {
    const r = await (await inquiry()).getForStaff(actor, id)
    if (r.ok) return r.data
    return r.error === "not_found" ? null : fail(r.error)
  },
  view: (rec) => ({
    title: `Inquiry ${rec.reference}`,
    summary: [
      { label: "Status", value: rec.status, kind: "status" },
      { label: "Kind", value: rec.kind },
      { label: "Received", value: rec.createdAt },
      { label: "Kept until", value: rec.expiresAt },
      { label: "Form", value: rec.form },
      { label: "Name", value: rec.name ?? "" },
      // 답하려면 전체 값이 필요하다 — 연락처 종류(contact)로 두면 콘솔이 가린다. 표에서는 가려서 나간다
      { label: rec.contactKind === "email" ? "Email" : "Phone", value: rec.contact },
      { label: "Message", value: rec.message },
      ...rec.replies.map((r, i) => ({ label: `Reply ${i + 1} · ${r.createdAt} · ${r.mailedAt ? "emailed" : "not emailed"}`, value: r.body })),
    ],
  }),
  form: {
    fields: (rec) => [{ name: "reply", label: rec.contactKind === "email" ? "Reply (emailed to the sender)" : "Reply (the sender left a phone number — saved here only, call back yourself)", type: "textarea", required: true, value: "" }],
    // 화면이 폼을 열 때 만든 중복 전송 방지 키(ctx.idempotencyKey)를 서비스에 그대로 넘긴다 — 두 번 눌러도, 응답이 늦어 다시 보내도 답변·메일은 한 번이다
    save: async (actor, rec, values, ctx) => {
      const r = await (await inquiry()).reply(actor, { reference: rec.reference, body: values.reply ?? "", ...(ctx.idempotencyKey ? { idempotencyKey: ctx.idempotencyKey } : {}) })
      if (!r.ok) {
        if (r.error === "in_progress") return refuse("invalid_state", { formError: "This reply is already being sent. Wait a moment, then check the thread before sending again." })
        return r.error === "invalid_input" ? refuse("invalid_input", { fieldErrors: { reply: ["Write a reply of up to 2000 characters."] } }) : fail(r.error)
      }
      if (r.data.mailed) return { message: "Reply saved and emailed to the sender." }
      return { message: rec.contactKind === "email" ? "Reply saved, but the email could not be sent — let the sender know another way." : "Reply saved. Nothing was emailed — the sender left a phone number." }
    },
  },
  actions: {
    "mark-in-progress": { label: "Mark in progress", when: (rec) => rec.status === "received", run: async (actor, rec) => done(await (await inquiry()).setStatus(actor, { reference: rec.reference, status: "in_progress" }), "Marked in progress.") },
    "mark-done": { label: "Mark done", when: (rec) => rec.status !== "done", run: async (actor, rec) => done(await (await inquiry()).setStatus(actor, { reference: rec.reference, status: "done" }), "Marked done.") },
    reopen: { label: "Reopen", when: (rec) => rec.status === "done", run: async (actor, rec) => done(await (await inquiry()).setStatus(actor, { reference: rec.reference, status: "in_progress" }), "Reopened.") },
    // 불만·분쟁은 3년 보관 대상이 된다(전자상거래법 시행령 제6조①4) — 올리는 일은 관리자만, 되돌리기는 종류 변경 서비스로 관리자만 한다
    "mark-complaint": {
      label: "Escalate to complaint",
      danger: true,
      adminOnly: true,
      when: (rec) => !DISPUTE.includes(rec.kind),
      run: async (actor, rec) => done(await (await inquiry()).markAsComplaint(rec.reference, actor, { reason: "Escalated in the admin console" }), "Escalated to a complaint. It is now kept for three years."),
    },
  },
  overview: async (actor) => {
    const r = await (await inquiry()).listForStaff(actor, { status: "received", limit: 1 })
    return r.ok && r.data.total > 0 ? { todo: [{ id: "received", severity: "warning", title: "New inquiries to answer", count: r.data.total, status: "received" }] } : {}
  },
})

export default inquiriesSection

// launch-factory: DB 연결. mock 은 메모리 PGlite(키 없이 켜진다), live 는 DATABASE_URL(Supabase 풀러 6543 — prepared statement 끔은 패키지가 한다).
// mock 의 마이그레이션은 이 앱에 설치된 db/migrations 를 쓴다(번들 안에서는 패키지 폴더를 찾을 수 없다).
import { join } from "node:path"
import { db, type Database } from "@launch-factory/db"
import { env, required } from "@/lib/launch/env"

let cached: Promise<Database> | undefined

/**
 * mock 의 메모리 DB 는 프로세스 하나에 하나다. 서버 번들은 쪽·서버 액션·경로 처리기(app/api)로 갈라져 같은 모듈이 번들마다 따로 불리므로(Next/Turbopack),
 * 모듈 변수에만 두면 번들 수만큼 DB 가 생겨 경로 처리기(웹훅·크론·/api/auth)와 쪽이 서로 다른 데이터를 보았다(관리 화면 시험 실측: 경로로 만든 세션이 쪽에서 안 보였다).
 * 그래서 globalThis 에 둔다. live 는 연결 문자열이 같은 DB 를 가리키므로 모듈 변수로 충분하다.
 */
const mockStore = globalThis as { __lfMockDb?: Promise<Database> }

export function database(): Promise<Database> {
  if (env().LF_MODE === "mock") return (mockStore.__lfMockDb ??= db.local({ migrationsFolder: join(process.cwd(), "db", "migrations") }))
  return (cached ??= Promise.resolve(db(required("DATABASE_URL"))))
}

// launch-factory: 환경 읽기. 이름만 다루고 값은 어디에도 남기지 않는다.
// LF_MODE 는 항상 필수다 — 없으면 켜지지 않는다(조용히 mock 으로 가지 않는다). live 에서는 공급자 키가 모두 필수다.
import { loadAppEnv, type AppEnv } from "@launch-factory/env"

let cached: AppEnv | undefined

/** 처음 부를 때 한 번 검사한다. 빠진 이름은 모두 모아 한 번에 알린다(값은 싣지 않는다). */
export function env(): AppEnv {
  return (cached ??= loadAppEnv())
}

/** 설정값·비밀값 하나를 읽는다. 없으면 이름만 담아 던진다. */
export function required(name: string): string {
  const value = (env() as Record<string, string | undefined>)[name] ?? process.env[name]
  if (!value) throw new Error(`${name} is not set (see .env.example)`)
  return value
}

/** 없어도 되는 설정값. */
export function optional(name: string): string | undefined {
  return process.env[name] || undefined
}

// launch-factory: 제품마다 고치는 값. 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
import type { Locale } from "@launch-factory/email"
import { env, required } from "@/lib/launch/env"

export const PRODUCT_NAME = "My Product"
/** 사용자 칸(user.locale)이 비었을 때 메일·오류 문구의 언어 */
export const DEFAULT_LOCALE: Locale = "en"
/** 가입 때 동의 기록에 남길 약관·개인정보 처리방침의 판. 문서를 고치면 올린다 */
export const CONSENT_VERSIONS = { terms: "2026-09-30", privacy: "2026-09-30" }
/** 결제 메일이 가리키는 화면 경로 */
export const ROUTES = { billing: "/account/billing", acceptPriceChange: "/account/billing/price-change", decline: "/account/billing/cancel", security: "/forgot-password", contact: "/contact" }

/** 앱 주소. mock 에서는 로컬 주소로 켜지고, live 에서는 NEXT_PUBLIC_APP_URL 이 필수다 */
export function appUrl(): string {
  // 빈 문자열은 없는 것으로 본다 — shadcn CLI 가 envVars 이름을 `NAME=`(빈 값)으로 .env.local 에 적는다
  return process.env.NEXT_PUBLIC_APP_URL || (env().LF_MODE === "mock" ? "http://localhost:3000" : required("NEXT_PUBLIC_APP_URL"))
}

// launch-factory: Cron 경로 인증. Vercel Cron 은 CRON_SECRET 이 있으면 `Authorization: Bearer <값>` 을 붙여 부른다
// (https://vercel.com/docs/cron-jobs/manage-cron-jobs#securing-cron-jobs). 값이 없거나 다르면 거절한다 — 비밀이 없으면 열어 두지 않는다.
import { timingSafeEqual } from "node:crypto"

export function cronAuthorized(request: Request): boolean {
  const secret = process.env.CRON_SECRET
  if (!secret) return false
  const given = request.headers.get("authorization") ?? ""
  const want = `Bearer ${secret}`
  return given.length === want.length && timingSafeEqual(Buffer.from(given), Buffer.from(want))
}

export const unauthorized = () => Response.json({ error: "unauthorized" }, { status: 401 })

// launch-factory: 마이그레이션 적용. 사용법: DATABASE_URL=<직접 연결(5432)> node db/migrate.mjs
// 이 폴더의 migrations/ 를 순서대로 적용한다. 이미 적용한 파일은 건너뛴다(drizzle 기록 표).
import { fileURLToPath } from "node:url"
import postgres from "postgres"
import { drizzle } from "drizzle-orm/postgres-js"
import { migrate } from "drizzle-orm/postgres-js/migrator"

const url = process.env.DATABASE_URL
if (!url) {
  console.error("DATABASE_URL is not set")
  process.exit(1)
}
if (new URL(url).port === "6543") {
  console.error("Use the direct connection (port 5432) for migrations, not the transaction pooler (6543).")
  process.exit(1)
}

const client = postgres(url, { max: 1 })
try {
  await migrate(drizzle(client), { migrationsFolder: fileURLToPath(new URL("./migrations", import.meta.url)) })
  console.log("migrations applied")
} finally {
  await client.end()
}

// 문의(v0 Task 15, 대장 D97 — 운영자 판정 2026-09-30 02:46 「v0로 앞당김」)와 폼 제출 멱등 키(D105).
// - inquiries: 문의 한 건. 개인정보는 최소만 — 이름(선택)·연락처(이메일 또는 전화)·문의 내용. IP·브라우저 정보는 저장하지 않는다.
//   보유 기간이 지나면(expires_at) purgeExpiredInquiries 가 지운다(개인정보 보호법 제21조① — 불필요해지면 지체 없이 파기).
//   기본 30일(D97). kind 가 complaint·dispute 인 문의는 소비자 불만·분쟁 처리 기록이라 전자상거래법 시행령 제6조①4에 따라 3년(D134).
//   kind 가 바뀌면 expires_at 도 접수일(created_at) 기준으로 다시 계산한다 — 바꾼 내역은 admin_actions 에 한 줄씩 남는다.
// - idempotency_keys: 폼을 열 때 만든 키 → 첫 성공 결과. 같은 키로 다시 보내면 24시간 동안 같은 결과를 돌려준다(Stripe 방식).
//   result 가 null 이면 처리 중이다. 실패한 제출은 남기지 않는다(고친 뒤 같은 키로 다시 보낼 수 있게).
// 시각은 앱이 넣는다(DB 기본값 now() 에 기대지 않는다 — Task 4 D26 규칙).
import { sql } from "drizzle-orm"
import { check, index, jsonb, pgTable, primaryKey, text, timestamp, uuid } from "drizzle-orm/pg-core"
import { user } from "./auth-base.ts"

const tz = { withTimezone: true } as const

/** 문의 종류(D134 — 운영자 판정 2026-09-30 03:35). complaint·dispute 는 소비자 불만·분쟁 처리 기록이라 3년, 나머지는 30일 */
export const INQUIRY_KINDS = ["general", "consultation", "quote", "complaint", "dispute"] as const
export type InquiryKind = (typeof INQUIRY_KINDS)[number]

/** 신청 처리 상태(계획 3c Task 5 — 내 신청 내역). 접수 → 처리 중 → 완료 */
export const INQUIRY_STATUSES = ["received", "in_progress", "done"] as const
export type InquiryStatus = (typeof INQUIRY_STATUSES)[number]

export const inquiries = pgTable(
  "inquiries",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** 사람에게 보이는 접수 번호(예: Q-7K3M9P2A) */
    reference: text("reference").notNull().unique(),
    /** 어느 폼에서 왔는지(블록 id 등, 개인정보 아님) */
    form: text("form").notNull(),
    name: text("name"),
    contact: text("contact").notNull(),
    contactKind: text("contact_kind").$type<"email" | "phone">().notNull(),
    message: text("message").notNull(),
    kind: text("kind").$type<InquiryKind>().notNull().default("general"),
    /** 처리 상태. 새 문의는 received — 바꾸는 일은 관리자·소유자만(admin_actions 에 한 줄) */
    status: text("status").$type<InquiryStatus>().notNull().default("received"),
    locale: text("locale").notNull(),
    /** 로그인한 채 보냈으면 그 사용자. 탈퇴하면 연결만 끊는다(문의 자체는 보유 기간까지) */
    userId: text("user_id").references(() => user.id, { onDelete: "set null" }),
    createdAt: timestamp("created_at", tz).notNull(),
    expiresAt: timestamp("expires_at", tz).notNull(),
    ownerNotifiedAt: timestamp("owner_notified_at", tz),
    receiptSentAt: timestamp("receipt_sent_at", tz),
  },
  (t) => [
    index("inquiries_expires_at_idx").on(t.expiresAt),
    index("inquiries_user_idx").on(t.userId, t.createdAt),
    check("inquiries_kind_check", sql`${t.kind} in ('general', 'consultation', 'quote', 'complaint', 'dispute')`),
    check("inquiries_status_check", sql`${t.status} in ('received', 'in_progress', 'done')`),
  ],
)

/**
 * 문의 답변(계획 3d 관리 화면). 직원(소유자·관리자)이 문의에 단 답 — 한 문의에 여러 번 달 수 있고 문의의 글타래가 된다.
 * 문의가 파기되면(expires_at) 답변도 같이 지워진다(on delete cascade) — 보유 기간은 문의 것을 따른다. mailed_at: 보낸 사람에게 메일이 나갔으면 그 시각(연락처가 전화이거나 메일이 실패하면 null).
 * 쓴 사람(admin_user_id)은 탈퇴하면 연결만 끊는다.
 */
export const inquiryReplies = pgTable(
  "inquiry_replies",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    inquiryId: uuid("inquiry_id")
      .notNull()
      .references(() => inquiries.id, { onDelete: "cascade" }),
    body: text("body").notNull(),
    adminUserId: text("admin_user_id").references(() => user.id, { onDelete: "set null" }),
    createdAt: timestamp("created_at", tz).notNull(),
    mailedAt: timestamp("mailed_at", tz),
  },
  (t) => [index("inquiry_replies_inquiry_idx").on(t.inquiryId, t.createdAt)],
).enableRLS() // 공개 표는 RLS 를 명시로 켠다(정책은 만들지 않는다 — 0010_explicit_rls)

export const idempotencyKeys = pgTable(
  "idempotency_keys",
  {
    /** 어느 제출인지(예: "inquiry", "checkout") — 같은 키라도 범위가 다르면 다른 요청이다 */
    scope: text("scope").notNull(),
    key: text("key").notNull(),
    result: jsonb("result"),
    createdAt: timestamp("created_at", tz).notNull(),
  },
  (t) => [primaryKey({ columns: [t.scope, t.key] }), index("idempotency_keys_created_at_idx").on(t.createdAt)],
)

-- 접속기록 위·변조 방지(「개인정보의 안전성 확보조치 기준」 제8조제3항). access_logs는 추가 전용이다.
--   UPDATE·TRUNCATE: 항상 거부
--   DELETE: 접속일시가 1년(제8조제1항 최소 보관 기간)을 넘은 행만 허용 — 파기 작업이 2년 설정이면 그보다 늦게 지운다
-- 트리거는 역할과 상관없이 걸린다(표 소유자가 트리거를 끄는 것까지는 막지 못한다 — 해시 사슬은 다음 단계, docs/qa/task-3-report.md).
CREATE FUNCTION "access_logs_append_only"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'TRUNCATE') THEN
    RAISE EXCEPTION 'access_logs is append-only: % refused', TG_OP;
  END IF;
  IF OLD.occurred_at > now() - interval '1 year' THEN
    RAISE EXCEPTION 'access_logs: rows younger than 1 year cannot be deleted';
  END IF;
  RETURN OLD;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "access_logs_no_update_delete" BEFORE UPDATE OR DELETE ON "access_logs" FOR EACH ROW EXECUTE FUNCTION "access_logs_append_only"();
--> statement-breakpoint
CREATE TRIGGER "access_logs_no_truncate" BEFORE TRUNCATE ON "access_logs" FOR EACH STATEMENT EXECUTE FUNCTION "access_logs_append_only"();

-- 증빙 기록 보호(v0 Task 14, 대장 D66③).
-- consent_records: 동의 이력은 고치지 않는다(UPDATE·TRUNCATE 거부). DELETE 는 허용한다 — 탈퇴 파기(개인정보 보호법 제21조제1항)가 지운다.
--   청약철회 제한 동의(withdrawal_limit)는 파기 전에 retained_transactions 로 옮긴다(전자상거래법 시행령 제6조제1항제2호).
-- retained_transactions: 보존 거래기록은 고치지 않는다(UPDATE·TRUNCATE 거부). DELETE 는 retain_until 이 지난 행만 허용한다 —
--   법정 기간(시행령 제6조제1항)이 끝나기 전에 지우지 못하게 한다.
-- 트리거는 역할과 상관없이 걸린다(표 소유자가 트리거를 끄는 것은 막지 못한다 — access_logs 와 같은 한계, task-3 보고).
CREATE FUNCTION "consent_records_no_update"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'consent_records is append-only: % refused', TG_OP;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "consent_records_no_update" BEFORE UPDATE ON "consent_records" FOR EACH ROW EXECUTE FUNCTION "consent_records_no_update"();
--> statement-breakpoint
CREATE TRIGGER "consent_records_no_truncate" BEFORE TRUNCATE ON "consent_records" FOR EACH STATEMENT EXECUTE FUNCTION "consent_records_no_update"();
--> statement-breakpoint
CREATE FUNCTION "retained_transactions_guard"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'TRUNCATE') THEN
    RAISE EXCEPTION 'retained_transactions is append-only: % refused', TG_OP;
  END IF;
  IF OLD.retain_until > now() THEN
    RAISE EXCEPTION 'retained_transactions: rows cannot be deleted before retain_until';
  END IF;
  RETURN OLD;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "retained_transactions_no_update_delete" BEFORE UPDATE OR DELETE ON "retained_transactions" FOR EACH ROW EXECUTE FUNCTION "retained_transactions_guard"();
--> statement-breakpoint
CREATE TRIGGER "retained_transactions_no_truncate" BEFORE TRUNCATE ON "retained_transactions" FOR EACH STATEMENT EXECUTE FUNCTION "retained_transactions_guard"();

